  const deps = new Map();
  const all = new Set();

  for (const key of Object.keys(graph)) {
    all.add(key);
    const list = graph[key];
    if (!Array.isArray(list)) {
      throw new Error('invalid graph: dependency list must be an array');
    }
    const unique = new Set();
    for (const d of list) {
      unique.add(d);
      all.add(d);
    }
    deps.set(key, unique);
  }

  for (const name of all) {
    if (!deps.has(name)) {
      deps.set(name, new Set());
    }
  }

  const placed = new Set();
  const result = [];

  while (result.length < all.size) {
    let next = null;
    for (const name of all) {
      if (placed.has(name)) continue;
      const ds = deps.get(name);
      let ready = true;
      for (const d of ds) {
        if (!placed.has(d)) {
          ready = false;
          break;
