  if (!m) {
    throw new RangeError('dateStr has the wrong shape');
  }

  const year = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const day = parseInt(m[3], 10);

  if (year < 1 || year > 9999) {
    throw new RangeError('year out of range');
  }

  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const isLeap = (y) => (y % 4 === 0 && y % 100 !== 0) || (y % 400 === 0);
  if (month < 1 || month > 12) {
    throw new RangeError('not a real calendar date');
  }
  const dim = daysInMonth[month - 1] + (month === 2 && isLeap(year) ? 1 : 0);
  if (day < 1 || day > dim) {
    throw new RangeError('not a real calendar date');
  }

  const base = Date.UTC(year, month - 1, day);
  const target = base + days * 86400000;

  const y = new Date(target).getUTCFullYear();
  if (y < 1 || y > 9999) {
    throw new RangeError('result year out of range');
  }

  const mo = new Date(target).getUTCMonth() + 1;
  const d = new Date(target).getUTCDate();

  const pad = (n) => String(n).padStart(2, '0');
  return `${String(y).padStart(4, '0')}-${pad(mo)}-${pad(d)}`;
}

