from collections import deque


def maze_steps(grid):
    if not grid:
        raise ValueError("grid must not be empty")

    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("rows must all have the same length")

    start = None
    end = None
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch not in "SE#.":
                raise ValueError("invalid character in grid")
            if ch == "S":
                if start is not None:
                    raise ValueError("exactly one S is required")
                start = (r, c)
            elif ch == "E":
                if end is not None:
                    raise ValueError("exactly one E is required")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("exactly one S and exactly one E are required")

    rows = len(grid)
    cols = width
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != "#":
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    return -1
